Future<void> load() async {try{final pa=await ui.FragmentProgram.fromAsset('shaders/fd2_glass.frag');final pb=await ui.FragmentProgram.fromAsset('shaders/fd4_glass.frag');if(!mounted)return;a=pa.fragmentShader();b=pb.fragmentShader();await scene();}catch(e){if(mounted)setState(()=>error=e.toString());}}
