final colors=dark?[0xff44374d,0xff304967,0xff4d4668,0xff325b60]:[0xffe6b9ae,0xff829fc9,0xffc4b5e4,0xff85bdb8];for(int i=0;i<16;i++){rect(i*20.0,0,20,200,Color(colors[i%4]));}c.drawCircle(const Offset(96.875,81.25),43.75,paint..color=Color(dark?0xff92b6e8:0xff344968));c.drawCircle(const Offset(221.875,118.75),51.25,paint..color=Color(dark?0xffd8a56d:0xfff4dfaf));if(app){rect(0,0,320,200,Color(dark?0xff23364e:0xffedf2f8));label('Today',20,12,15,Color(dark?0xffb9d2f4:0xff23364e));for(int j=0;j<3;j++){rect(20,40+j*47.0,279,36,Color(dark?0xff405b78:0xffb7cce8));label(['Your activity','Recent messages','Discover more'][j],31,49+j*47.0,10,Color(dark?0xffffffff:0xff23364e));}}if(moving)c.drawCircle(Offset(160+math.sin(phase)*109.375,100),15,paint..color=Color(dark?0xffa9c7ff:0xffe879a0));final pic=rec.endRecording();try{final next=await pic.toImage(1024,640);ui.Image? sa,sb;try{sa=await soften(next,math.sqrt(sigma*sigma+rough*rough*81));sb=await soften(next,sigma);}catch(e){next.dispose();sa?.dispose();sb?.dispose();rethrow;}if(!mounted){next.dispose();sa?.dispose();sb?.dispose();return;}final old=image,oa=softA,ob=softB;setState((){image=next;softA=sa;softB=sb;displayedPhase=capturePhase;displayedDark=captureDark;displayedApp=captureApp;displayedMoving=captureMoving;});WidgetsBinding.instance.addPostFrameCallback((_){old?.dispose();oa?.dispose();ob?.dispose();});}catch(e){if(mounted)setState(()=>error=e.toString());}finally{pic.dispose();busy=false;if(queued&&mounted){queued=false;scene();}}}
