void tick(Duration now){double dt=((now-last).inMicroseconds/1e6).clamp(0,.04).toDouble();last=now;frames++;frameSeconds+=dt;if(frameSeconds>=.5){fps=frames/frameSeconds;frames=0;frameSeconds=0;}while(dt>0){final h=math.min(dt,1/240);velocity+=(-p['stiffness']!*(progress-target)-p['damping']!*velocity)/p['mass']!*h;progress+=velocity*h;dt-=h;if(moving)phase+=h;}if((progress-target).abs()<.001&&velocity.abs()<.005){progress=target;velocity=0;if(!moving)ticker.stop();}if(moving)scene();setState((){});}
