Widget tile(String name,ui.FragmentShader? shader,double model)=>Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.start,children:[Text(name,style:const TextStyle(fontSize:13)),const SizedBox(height:4),AspectRatio(aspectRatio:1.6,child:ClipRRect(borderRadius:BorderRadius.circular(8),child:Stack(fit:StackFit.expand,children:[if(image!=null&&shader!=null&&softA!=null&&softB!=null)CustomPaint(painter:PortPainter(image!,model==0?softA!:softB!,shader,Map.of(p),progress,displayedDark,model)),Center(child:Text('Optical Glass',style:TextStyle(fontSize:14,fontWeight:FontWeight.bold,color:displayedDark?Colors.white:const Color(0xff172337))))])))]);
@override Widget build(BuildContext context)=>MaterialApp(theme:ThemeData.dark(),home:Scaffold(body:SafeArea(child:LayoutBuilder(builder:(context,box){final w=math.min(box.maxWidth-24,960.0);final half=(w-8)/2;return Center(child:SizedBox(width:w,child:Column(children:[const Text('FMDS Render Lab v0.4.1',style:TextStyle(fontSize:20)),const Text('Continuous sampling · experimental'),Wrap(children:[TextButton(onPressed:(){target=target==1?0:1;start();},child:const Text('Morph')),TextButton(onPressed:(){setState((){target=target==1?0:1;progress=target;velocity=0;});},child:const Text('Shape')),TextButton(onPressed:(){setState(()=>app=!app);scene();},child:const Text('Scene')),TextButton(onPressed:(){setState(()=>dark=!dark);scene();},child:const Text('Theme')),TextButton(onPressed:(){setState(()=>moving=!moving);start();scene();},child:const Text('Dynamic')),TextButton(onPressed:(){setState(()=>p.addAll(specs.map((k,v)=>MapEntry(k,v[3]))));scene();},child:const Text('Reset'))]),if(error!=null)Text(error!),SizedBox(height:math.min(half/1.6*2+52,box.maxHeight*.58),child:Row(crossAxisAlignment:CrossAxisAlignment.start,children:[Expanded(child:referenceView({'type':'fmds-state','params':p,'dark':displayedDark,'app':displayedApp,'dynamic':displayedMoving,'phase':displayedPhase,'progress':progress})),const SizedBox(width:8),Expanded(child:SingleChildScrollView(child:Column(children:[tile('F-D2 · analytic approximation',a,0),const SizedBox(height:8),tile('F-D4 · GPU port',b,1)]))) ])),Text('D2/F-D2: env, bevel, depth, exposure, crown, roughness. F-D2/F-D4 share scene; blur uses Gaussian texture. Ticker ~${fps.toStringAsFixed(0)} Hz (not GPU FPS).',style:const TextStyle(fontSize:11)),Expanded(child:ListView(children:[for(final e in specs.entries)Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${e.key}: ${p[e.key]!.toStringAsFixed(3)}'),Slider(value:p[e.key]!,min:e.value[0],max:e.value[1],onChanged:(v){setState(()=>p[e.key]=v);if(e.key=='blur'||e.key=='roughn